/* Locally hosted neural voice clips: no device-TTS dependency. */
(()=>{let player=null,token=0;const $=s=>document.querySelector(s);const buddy=`<div class="buddy-avatar"><div class="mascot"><i class="ear l"></i><i class="ear r"></i><i class="eyes"></i><i class="cheek"></i><span class="mouth">ᴗ</span><i class="scarf"></i><i class="paw left"></i><i class="paw right"></i></div></div>`;
function mood(value){document.querySelectorAll('.mascot').forEach(el=>{el.classList.remove('talking','cheering','thinking');if(value)el.classList.add(value)})}
function cancel(){token++;if(player){player.pause();player.currentTime=0;player=null}mood('');document.querySelectorAll('.voice-playing').forEach(el=>el.classList.remove('voice-playing'))}
async function play(text,rate=.85){cancel();const key=window.TORI_VOICES?.[text];if(!key){const f=$('#feedback');if(f)f.textContent='이 소리를 불러오지 못했어요. 다른 문제로 이동해 주세요.';return}const id=token;player=new Audio(key);player.playbackRate=Math.min(1.15,Math.max(.75,Number(rate)/.85));player.onplay=()=>{if(id!==token)return;mood('talking');$('#listen')?.classList.add('voice-playing')};player.onended=()=>{if(id===token){mood('');$('#listen')?.classList.remove('voice-playing')}};player.onerror=()=>{if(id===token){cancel();const f=$('#feedback');if(f)f.textContent='음성을 불러오지 못했어요. 인터넷 연결을 확인하고 다시 눌러 주세요.'}};try{await player.play()}catch{if(id===token){cancel();const f=$('#feedback');if(f)f.textContent='소리 듣기 버튼을 다시 눌러 주세요.'}}}
function tone(kind){if(!window.AudioContext&&!window.webkitAudioContext)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const notes=kind==='success'?[523.25,659.25,783.99,1046.5]:[392,523.25];notes.forEach((freq,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,ctx.currentTime+i*.09);g.gain.linearRampToValueAtTime(.075,ctx.currentTime+i*.09+.015);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.09+.2);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*.09);o.stop(ctx.currentTime+i*.09+.22)});setTimeout(()=>ctx.close(),1000)}catch{}}
function react(kind,sound){const panel=$('.panel')||$('.hero');if(!panel)return;panel.classList.remove('success-burst','gentle-wiggle');void panel.offsetWidth;panel.classList.add(kind==='success'?'success-burst':'gentle-wiggle');mood(kind==='success'?'cheering':'thinking');const bubble=$('.buddy-bubble');if(bubble)bubble.textContent=kind==='success'?'야호! 해냈어! ⭐':'괜찮아! 함께 해보자 💛';if(sound)tone(kind);if(kind==='success'){const layer=document.createElement('div');layer.className='confetti-layer';layer.setAttribute('aria-hidden','true');for(let i=0;i<24;i++){const star=document.createElement('i');star.textContent=['★','✦','●','♥'][i%4];star.style.cssText=`--x:${Math.random()*100}%;--r:${Math.random()*720-360}deg;--delay:${Math.random()*.3}s;--color:${['#f6c747','#57bba2','#f18ca2','#9c8bdb'][i%4]}`;layer.append(star)}panel.append(layer);setTimeout(()=>layer.remove(),2000)}}
function mount(){const panel=$('.panel');if(panel&&!$('.activityBuddy')){const b=document.createElement('div');b.className='activityBuddy';b.innerHTML=buddy+'<div class="buddy-bubble">토리와 함께라면 할 수 있어! 🌱</div>';panel.querySelector('.progress').after(b)}const hero=$('.heroText');if(hero&&!$('#voicePreview')){const button=document.createElement('button');button.id='voicePreview';button.className='voice-preview';button.textContent='▶ 새로워진 토리 목소리 듣기';button.onclick=()=>window.toriWelcome?.();hero.append(button)}document.querySelectorAll('.card').forEach((el,i)=>el.style.setProperty('--order',i));}
window.ToriMagic={play,cancel,react,mount};})();
